<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import ProductPicker from './ProductPicker.vue'
import UnitPicker from './UnitPicker.vue'
import { apiError, can, dateTime, jsonBody, localDateTimeInput, money, opsRequest, pageParams, type Row } from './shared'

const props = defineProps<{ token: string; permissions: string[]; initialProductId?: string }>()
const writable = computed(() => can(props.permissions, 'sales:write'))
const rows = ref<Row[]>([]), total = ref(0), page = ref(1), size = ref(10), q = ref(''), loading = ref(false), error = ref('')
const stores = ref<Row[]>([]), campaigns = ref<Row[]>([]), warehouses=ref<Row[]>([]), reservedUnits=ref<Row[]>([]), showEditor = ref(false), detail = ref<Row | null>(null), showRefund = ref(false), refundOrder = ref<Row | null>(null), showSupplement = ref(false), supplementOrder = ref<Row | null>(null), showStockDialog=ref(false), stockOperation=ref<'reserve'|'release'>('reserve')
const stockForm=reactive({sales_order_id:'',warehouse_id:'',occurred_at:localDateTimeInput(),reason:'',unit_ids:[] as string[]})
const form = reactive<any>({ external_number: '', channel: '', store_id: '', customer_name: '', recipient_phone: '', shipping_address: '', ordered_at: '', shipping_amount: '0', notes: '', items: [] as Row[], discounts: [] as Row[], discounts_complete: true, paid_amount: '' })
const refund = reactive({ amount: '', reason: '' })
let timer: ReturnType<typeof setTimeout> | undefined
const statusLabels: Record<string,string> = { open:'待发货', partial:'部分发货', shipped:'已发货', cancelled:'已取消' }

async function load() {
  loading.value = true; error.value = ''
  try { const result = await opsRequest<{items:Row[];total:number}>(props.token, `/orders?${pageParams(page.value,size.value,q.value)}`); rows.value=result.items; total.value=result.total }
  catch(e){error.value=apiError(e)} finally{loading.value=false}
}
async function loadOptions(){
  const results=await Promise.allSettled([opsRequest<Row[]>(props.token,'/stores'),opsRequest<{items:Row[];total:number}>(props.token,'/campaigns?page=1&size=50&q='),opsRequest<Row[]>(props.token,'/warehouses')])
  if(results[0].status==='fulfilled') stores.value=results[0].value
  else error.value=apiError(results[0].reason)
  if(results[1].status==='fulfilled') campaigns.value=results[1].value.items
  else error.value=apiError(results[1].reason)
  if(results[2].status==='fulfilled') warehouses.value=results[2].value
  else error.value=apiError(results[2].reason)
}
watch(q,()=>{clearTimeout(timer);page.value=1;timer=setTimeout(()=>void load(),300)})
watch(page,()=>void load())
watch(size,()=>{page.value=1;void load()})
onMounted(async()=>{await Promise.all([load(),loadOptions()]);if(props.initialProductId)openCreate(props.initialProductId)})
function openCreate(productId=''){
  Object.assign(form,{external_number:'',channel:'',store_id:'',customer_name:'',recipient_phone:'',shipping_address:'',ordered_at:localDateTimeInput(),shipping_amount:'0',notes:'',items:productId?[{product_id:productId,product_label:'',quantity:1,unit_price:'',campaign_id:''}]:[],discounts:[],discounts_complete:true,paid_amount:''})
  detail.value=null;showEditor.value=true
}
function addItem(product?:Row|null){form.items.push({product_id:product?.id||'',product_label:product?`${product.sku} · ${product.name}`:'',quantity:1,unit_price:'',campaign_id:''})}
function removeItem(index:number|string){form.items.splice(Number(index),1)}
function addDiscount(){form.discounts.push({name:'',amount:'',bearer:'merchant',product_id:''})}
function removeDiscount(index:number|string){form.discounts.splice(Number(index),1)}
const calculatedAmount=computed(()=>form.items.reduce((sum:number,item:Row)=>sum+Number(item.quantity||0)*Number(item.unit_price||0),0))
async function save(){
  if(!form.channel.trim()||!form.customer_name.trim()||!form.ordered_at||!form.items.length||form.items.some((i:Row)=>!i.product_id||!i.quantity||!i.unit_price)||form.paid_amount===''){error.value='请填写渠道、收货方、订单时间、商品明细和买家实付';return}
  const payload={external_number:form.external_number||undefined,channel:form.channel,store_id:form.store_id||undefined,customer_name:form.customer_name,recipient_phone:form.recipient_phone||undefined,shipping_address:form.shipping_address||undefined,ordered_at:new Date(form.ordered_at).toISOString(),shipping_amount:String(form.shipping_amount||0),notes:form.notes,items:form.items.map((i:Row)=>({product_id:i.product_id,quantity:Number(i.quantity),unit_price:String(i.unit_price),...(i.campaign_id?{campaign_id:i.campaign_id}:{})})),discounts:form.discounts.map((d:Row)=>({name:d.name,amount:String(d.amount),bearer:d.bearer,...(d.product_id?{product_id:d.product_id}:{})})),discounts_complete:form.discounts_complete,paid_amount:String(form.paid_amount)}
  loading.value=true;error.value=''
  try{await opsRequest(props.token,'/orders',{method:'POST',body:jsonBody(payload)});showEditor.value=false;await load();ElMessage.success('销售订单已创建')}
  catch(e){error.value=apiError(e)}finally{loading.value=false}
}
async function openDetail(row:Row){loading.value=true;error.value='';try{detail.value=await opsRequest<Row>(props.token,`/orders/${row.id}`);const result=await opsRequest<{items:Row[];total:number}>(props.token,`/units?reserved_order_id=${encodeURIComponent(row.id)}&status=reserved&page=1&size=50`);reservedUnits.value=result.items}catch(e){error.value=apiError(e)}finally{loading.value=false}}
async function cancelOrder(row:Row){error.value='';loading.value=true;try{await opsRequest(props.token,`/orders/${row.id}/cancel`,{method:'POST'});ElMessage.success('订单已取消');await load();if(detail.value?.id===row.id)await openDetail(row)}catch(e){error.value=apiError(e)}finally{loading.value=false}}
function beginRefund(row:Row){refundOrder.value=row;Object.assign(refund,{amount:'',reason:''});showRefund.value=true}
async function submitRefund(){if(!refundOrder.value||!refund.amount||!refund.reason.trim()){error.value='请填写退款金额和原因';return}loading.value=true;try{await opsRequest(props.token,`/orders/${refundOrder.value.id}/refunds`,{method:'POST',body:jsonBody({amount:String(refund.amount),reason:refund.reason})});showRefund.value=false;ElMessage.success('退款记录已保存');await load();if(detail.value?.id===refundOrder.value.id)await openDetail(refundOrder.value)}catch(e){error.value=apiError(e)}finally{loading.value=false}}
function beginSupplement(row:Row){supplementOrder.value=row;form.discounts=(row.discounts||[]).map((d:Row)=>({name:d.name,amount:d.amount,bearer:d.bearer,product_id:d.product_id||''}));showSupplement.value=true}
async function submitSupplement(){if(!supplementOrder.value||form.discounts.some((d:Row)=>!d.name.trim()||d.amount===''||!d.bearer)){error.value='请补全每项优惠的名称、金额和承担方';return}loading.value=true;try{await opsRequest(props.token,`/orders/${supplementOrder.value.id}/discounts`,{method:'POST',body:jsonBody({discounts:form.discounts.map((d:Row)=>({name:d.name,amount:String(d.amount),bearer:d.bearer,...(d.product_id?{product_id:d.product_id}:{})})),discounts_complete:true})});showSupplement.value=false;ElMessage.success('实际优惠明细已补录');await openDetail(supplementOrder.value);await load()}catch(e){error.value=apiError(e)}finally{loading.value=false}}
function beginStockOperation(action:'reserve'|'release',row:Row){stockOperation.value=action;Object.assign(stockForm,{sales_order_id:row.id,warehouse_id:warehouses.value[0]?.id||'',occurred_at:localDateTimeInput(),reason:action==='reserve'?'订单备货':'取消预留',unit_ids:[]});showStockDialog.value=true}
async function submitStockOperation(){if(!stockForm.sales_order_id||!stockForm.warehouse_id||!stockForm.unit_ids.length||!stockForm.reason.trim()){error.value='请选择仓库和单件，并填写操作原因';return}loading.value=true;try{await opsRequest(props.token,`/${stockOperation.value==='reserve'?'reservations':'releases'}`,{method:'POST',body:jsonBody({...stockForm,occurred_at:new Date(stockForm.occurred_at).toISOString()})});showStockDialog.value=false;ElMessage.success(stockOperation.value==='reserve'?'库存已为订单预留':'订单预留已释放');if(detail.value)await openDetail(detail.value)}catch(e){error.value=apiError(e)}finally{loading.value=false}}
</script>

<template>
  <section>
    <header class="ops-toolbar"><div><div class="eyebrow">COMMERCE / SALES</div><h1>销售订单</h1><p class="section-lead">手工记录成交、实际优惠和运费；查看订单履约、退款与发货明细。</p></div><div class="ops-actions"><el-input v-model="q" class="ops-search" clearable placeholder="搜索订单号、客户或外部单号"/><el-button v-if="writable" type="primary" @click="openCreate()">新建销售订单</el-button></div></header>
    <p v-if="error" class="ops-error">{{ error }}</p>
    <div v-if="!detail" class="panel ops-panel"><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th style="width:15%">销售单号</th><th style="width:15%">外部单号</th><th style="width:13%">渠道 / 店铺</th><th style="width:16%">客户或收货方</th><th style="width:13%">下单时间</th><th style="width:12%">状态</th><th style="width:10%">买家实付</th><th style="width:6%">操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td class="ops-row-title" :title="row.number">{{ row.number }}</td><td :title="row.external_number">{{ row.external_number || '—' }}</td><td :title="`${row.channel} ${row.store_name||''}`">{{ row.channel }}<small v-if="row.store_name"> · {{ row.store_name }}</small></td><td :title="row.customer_name">{{ row.customer_name }}</td><td>{{ dateTime(row.ordered_at) }}</td><td><span class="ops-chip">{{ statusLabels[row.status]||row.status }}</span></td><td>{{ money(row.paid_amount) }}</td><td><el-button link @click="openDetail(row)">详情</el-button></td></tr></tbody></table><div v-if="!rows.length&&!loading" class="ops-empty">暂无销售订单</div></div><div class="ops-pagination"><span>共 {{ total }} 条</span><el-select v-model="size" style="width:95px"><el-option :value="10" label="10 条/页"/><el-option :value="20" label="20 条/页"/><el-option :value="50" label="50 条/页"/></el-select><el-button :disabled="page<=1" @click="page--">上一页</el-button><span>第 {{ page }} 页</span><el-button :disabled="page*size>=total" @click="page++">下一页</el-button></div></div>
    <div v-else class="panel ops-panel"><div class="panel-heading"><div><div class="eyebrow">SALES ORDER DETAIL</div><h3>{{ detail.number }}</h3></div><div class="ops-actions"><el-button v-if="writable && ['open','partial'].includes(detail.status)" @click="beginStockOperation('reserve',detail)">预留库存</el-button><el-button v-if="writable && reservedUnits.length" @click="beginStockOperation('release',detail)">释放预留</el-button><el-button v-if="writable && detail.status==='open'" @click="cancelOrder(detail)">取消未发货订单</el-button><el-button v-if="writable && !detail.discounts_complete" @click="beginSupplement(detail)">补录优惠明细</el-button><el-button v-if="writable && detail.status!=='cancelled'" type="primary" @click="beginRefund(detail)">登记退款</el-button><el-button @click="detail=null">返回订单列表</el-button></div></div>
      <div class="ops-detail"><div><label>外部订单号</label><strong>{{ detail.external_number||'—' }}</strong></div><div><label>渠道 / 店铺</label><strong>{{ detail.channel }} · {{ detail.store_name||'—' }}</strong></div><div><label>客户或收货方</label><strong>{{ detail.customer_name }}</strong></div><div><label>联系电话</label><strong>{{ detail.recipient_phone||'—' }}</strong></div><div class="span-two"><label>收货地址</label><strong :title="detail.shipping_address">{{ detail.shipping_address||'—' }}</strong></div><div><label>下单时间 / 状态</label><strong>{{ dateTime(detail.ordered_at) }} · {{ statusLabels[detail.status]||detail.status }}</strong></div><div><label>优惠明细</label><strong>{{ detail.discounts_complete?'已核对':'待补录' }}</strong></div><div><label>商品原金额</label><strong>{{ money(detail.original_amount) }}</strong></div><div><label>已录入优惠</label><strong>{{ money(detail.discount_amount) }}</strong></div><div><label>待补优惠金额</label><strong>{{ money(detail.undisclosed_discount_amount) }}</strong></div><div><label>买家实付</label><strong>{{ money(detail.paid_amount) }}</strong></div><div><label>运费 / 已退款</label><strong>{{ money(detail.shipping_amount) }} / {{ money(detail.refunded_amount) }}</strong></div><div class="span-two"><label>备注</label><strong :title="detail.notes">{{ detail.notes||'—' }}</strong></div></div>
      <h3>商品明细</h3><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>商品</th><th>数量</th><th>单价</th><th>原金额</th><th>优惠</th><th>实付</th><th>活动</th></tr></thead><tbody><tr v-for="item in detail.items||[]" :key="item.id"><td :title="`${item.sku} ${item.name}`">{{ item.sku }} · {{ item.name }}</td><td>{{ item.quantity }}</td><td>{{ money(item.unit_price) }}</td><td>{{ money(item.original_amount) }}</td><td>{{ money(item.discount_amount) }}</td><td>{{ money(item.paid_amount) }}</td><td :title="item.campaign_name">{{ item.campaign_name||'—' }}</td></tr></tbody></table></div>
      <h3 style="margin-top:20px">实际优惠</h3><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>优惠名称</th><th>承担方</th><th>金额</th><th>商品</th></tr></thead><tbody><tr v-for="d in detail.discounts||[]" :key="d.id"><td>{{ d.name }}</td><td>{{ d.bearer==='merchant'?'商家':'平台' }}</td><td>{{ money(d.amount) }}</td><td>{{ d.sku||'订单级优惠' }}</td></tr><tr v-if="!detail.discounts?.length"><td colspan="4">暂无优惠明细</td></tr></tbody></table></div>
      <h3 style="margin-top:20px">已预留实物</h3><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>商品</th><th>序列号 / 批次</th><th>仓库</th><th>状态</th></tr></thead><tbody><tr v-for="unit in reservedUnits" :key="unit.id"><td>{{ unit.sku }} · {{ unit.name }}</td><td>{{ unit.serial_number||unit.batch_number }}</td><td>{{ unit.warehouse_name||'—' }}</td><td>已预留</td></tr><tr v-if="!reservedUnits.length"><td colspan="4">当前没有预留库存</td></tr></tbody></table></div>
      <h3 style="margin-top:20px">发货记录</h3><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>发货单号</th><th>发货时间</th><th>物流公司</th><th>运单号</th><th>物流费用</th><th>实物</th></tr></thead><tbody><tr v-for="shipment in detail.shipments||[]" :key="shipment.id"><td>{{ shipment.number }}</td><td>{{ dateTime(shipment.occurred_at) }}</td><td>{{ shipment.carrier||'—' }}</td><td>{{ shipment.tracking_number||'—' }}</td><td>{{ money(shipment.shipping_cost) }}</td><td :title="(shipment.items||[]).map((u:Row)=>u.serial_number||u.unit_id).join('、')">{{ (shipment.items||[]).map((u:Row)=>u.serial_number||u.unit_id).join('、')||'—' }}</td></tr><tr v-if="!detail.shipments?.length"><td colspan="6">暂无发货记录；库存出库单与订单关联后显示在此处</td></tr></tbody></table></div>
    </div>
    <el-dialog v-model="showEditor" title="新建销售订单" width="980px" destroy-on-close><div class="ops-form-grid"><el-form-item label="渠道"><el-input v-model="form.channel" placeholder="如：天猫旗舰店"/></el-form-item><el-form-item label="店铺"><el-select v-model="form.store_id" clearable placeholder="可选" style="width:100%"><el-option v-for="store in stores" :key="store.id" :label="`${store.platform} · ${store.name}`" :value="store.id"/></el-select></el-form-item><el-form-item label="外部订单号"><el-input v-model="form.external_number"/></el-form-item><el-form-item label="客户或收货方"><el-input v-model="form.customer_name"/></el-form-item><el-form-item label="联系电话（可选）"><el-input v-model="form.recipient_phone"/></el-form-item><el-form-item label="下单时间"><el-date-picker v-model="form.ordered_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="收货地址（可选）" class="span-two"><el-input v-model="form.shipping_address"/></el-form-item><el-form-item label="运费"><el-input v-model="form.shipping_amount"/></el-form-item><el-form-item label="买家实付"><el-input v-model="form.paid_amount" placeholder="按平台实际成交金额填写"/></el-form-item><el-form-item label="商品原金额参考"><strong>{{ money(calculatedAmount) }}</strong></el-form-item><el-form-item label="备注" class="span-two"><el-input v-model="form.notes" type="textarea" :rows="2"/></el-form-item></div>
      <div class="panel-heading"><h3>商品明细</h3><span class="ops-muted">商品价格和活动归属作为成交快照保存</span></div><div v-for="(item,index) in form.items" :key="index" class="ops-line-row"><ProductPicker v-model="item.product_id" :token="token" @select="(product)=>item.product_label=product?`${product.sku} · ${product.name}`:''"/><el-input-number v-model="item.quantity" :min="1" :step="1" style="width:100%"/><el-input v-model="item.unit_price" placeholder="优惠前原单价"/><el-select v-model="item.campaign_id" clearable placeholder="活动（可选）"><el-option v-for="campaign in campaigns" :key="campaign.id" :label="campaign.name" :value="campaign.id"/></el-select><el-button link type="danger" @click="removeItem(Number(index))">移除</el-button></div><el-button @click="addItem()">＋ 添加商品</el-button>
      <div class="panel-heading" style="margin-top:18px"><h3>实际优惠明细</h3><span class="ops-muted">优惠未知时标记为待补，不要估算或填零</span></div><el-checkbox v-model="form.discounts_complete">优惠明细已完整核对</el-checkbox><div v-for="(discount,index) in form.discounts" :key="index" class="ops-line-row" style="grid-template-columns:1.3fr 1fr 120px 1fr auto"><el-input v-model="discount.name" placeholder="优惠名称"/><el-input v-model="discount.amount" placeholder="实际优惠金额"/><el-select v-model="discount.bearer"><el-option label="商家承担" value="merchant"/><el-option label="平台承担" value="platform"/></el-select><ProductPicker v-model="discount.product_id" :token="token" placeholder="关联商品（可选）"/><el-button link type="danger" @click="removeDiscount(Number(index))">移除</el-button></div><el-button @click="addDiscount">＋ 添加优惠</el-button><p v-if="error" class="ops-error">{{ error }}</p><template #footer><el-button @click="showEditor=false">取消</el-button><el-button type="primary" :loading="loading" @click="save">保存销售订单</el-button></template></el-dialog>
    <el-dialog v-model="showStockDialog" :title="stockOperation==='reserve'?'为订单预留库存':'释放订单预留'" width="820px" destroy-on-close><div class="ops-detail"><div><label>销售订单</label><strong>{{ detail?.number }}</strong></div><div><label>操作类型</label><strong>{{ stockOperation==='reserve'?'预留可用实物':'释放此订单的预留实物' }}</strong></div></div><div class="ops-form-grid"><el-form-item label="仓库"><el-select v-model="stockForm.warehouse_id" style="width:100%"><el-option v-for="warehouse in warehouses" :key="warehouse.id" :label="warehouse.name" :value="warehouse.id"/></el-select></el-form-item><el-form-item label="发生时间"><el-date-picker v-model="stockForm.occurred_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="原因" class="span-two"><el-input v-model="stockForm.reason"/></el-form-item></div><UnitPicker v-model="stockForm.unit_ids" :token="token" :status="stockOperation==='reserve'?'available':'reserved'" :warehouse-id="stockForm.warehouse_id" :reserved-order-id="stockOperation==='release'?stockForm.sales_order_id:''"/><p v-if="error" class="ops-error">{{ error }}</p><template #footer><el-button @click="showStockDialog=false">取消</el-button><el-button type="primary" :loading="loading" @click="submitStockOperation">{{ stockOperation==='reserve'?'确认预留':'确认释放' }}</el-button></template></el-dialog>
    <el-dialog v-model="showSupplement" title="补录实际优惠明细" width="820px" destroy-on-close><div class="ops-muted">订单 {{ supplementOrder?.number }} · 只填写平台已实际使用的优惠，金额与承担方应与成交记录一致。</div><div v-for="(discount,index) in form.discounts" :key="index" class="ops-line-row" style="grid-template-columns:1.3fr 1fr 120px 1fr auto"><el-input v-model="discount.name" placeholder="优惠名称"/><el-input v-model="discount.amount" placeholder="实际优惠金额"/><el-select v-model="discount.bearer"><el-option label="商家承担" value="merchant"/><el-option label="平台承担" value="platform"/></el-select><ProductPicker v-model="discount.product_id" :token="token" placeholder="关联商品（可选）"/><el-button link type="danger" @click="removeDiscount(Number(index))">移除</el-button></div><el-button @click="addDiscount">＋ 添加优惠</el-button><p v-if="error" class="ops-error">{{ error }}</p><template #footer><el-button @click="showSupplement=false">取消</el-button><el-button type="primary" :loading="loading" @click="submitSupplement">保存完整优惠明细</el-button></template></el-dialog>
    <el-dialog v-model="showRefund" title="登记退款" width="500px"><div class="ops-muted">退款仅记录资金变化，不会增加库存。实物退回需单独办理入库。</div><el-form-item label="退款金额"><el-input v-model="refund.amount"/></el-form-item><el-form-item label="退款原因"><el-input v-model="refund.reason" type="textarea" :rows="3"/></el-form-item><p v-if="error" class="ops-error">{{ error }}</p><template #footer><el-button @click="showRefund=false">取消</el-button><el-button type="primary" :loading="loading" @click="submitRefund">保存退款</el-button></template></el-dialog>
  </section>
</template>
